def main():
    combined = SCAM_TRAIN + INTENT_TRAIN
    print(f"Total training examples synthesized: {len(combined)}")
    print(f"  - Scam Detection: {len(SCAM_TRAIN)}")
    print(f"  - Intent Classification: {len(INTENT_TRAIN)}")

    # Verify zero leakage with benchmark_100.json
    with open("data/benchmark_100.json", "r", encoding="utf-8") as f:
        test_data = json.load(f)

    test_inputs = {q["input"].strip().lower() for q in test_data}
    train_inputs = {q["input"].strip().lower() for q in combined}

    overlap = test_inputs.intersection(train_inputs)
    assert len(overlap) == 0, f"DATA LEAKAGE DETECTED! Overlap: {len(overlap)}"
    print("[SUCCESS] Zero-leakage verified: 0 test questions appear in the training dataset!")

    out_path = "data/train_scam_intent_sota.json"
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(combined, f, indent=2)

    print(f"Saved SOTA training dataset to: {out_path}")


if __name__ == "__main__":
    main()
